      ELSIF enb = '1' THEN
        Delay1_delOut_2 <= Delay1_delOut_1;
      END IF;
    END IF;
  END PROCESS delayMatch4_process;


  Delay2_bypass_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset_x = '1' THEN
        Delay2_bypass_reg <= X"00000000";
      ELSIF enb_1_81_1 = '1' THEN
        Delay2_bypass_reg <= phi_mech_int_2;
      END IF;
    END IF;
  END PROCESS Delay2_bypass_process;

  
  Delay2_out1 <= phi_mech_int_2 WHEN enb_1_81_1 = '1' ELSE
      Delay2_bypass_reg;

  
  phi_mech_int <= Delay1_delOut_2 WHEN phi_reset = '0' ELSE
      Delay1_iv;

  reduced_1_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset_x = '1' THEN
        phi_mech_int_2 <= X"00000000";
      ELSIF enb = '1' THEN
        phi_mech_int_2 <= phi_mech_int;
      END IF;
    END IF;
  END PROCESS reduced_1_process;


  reduced_2_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset_x = '1' THEN
        reduced_reg <= (OTHERS => X"00000000");
      ELSIF enb = '1' THEN
        reduced_reg(0) <= phi_mech_int_2;
        reduced_reg(1 TO 57) <= reduced_reg(0 TO 56);
      END IF;
    END IF;
  END PROCESS reduced_2_process;

  phi_mech_int_3 <= reduced_reg(57);

  phi_mech <= Product_out1;

  theta <= Product3_out1;

END rtl;

